class DSU:
    def __init__(self, n):
        self.n = n
        self.parent = list(range(n + 1))
    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        self.parent[ra] = rb
        return True
    def connected(self):
        return all(self.find(i) == self.find(1) for i in range(2, self.n + 1))

def max_num_edges_to_remove(n, edges):
    alice, bob = DSU(n), DSU(n)
    used = 0
    for t, u, v in edges:
        if t == 3:
            a = alice.union(u, v)
            b = bob.union(u, v)
            if a or b:
                used += 1                                          # shared edges processed FIRST
    for t, u, v in edges:
        if t == 1 and alice.union(u, v):
            used += 1
        elif t == 2 and bob.union(u, v):
            used += 1
    if not alice.connected() or not bob.connected():
        return -1
    return len(edges) - used

